cypress_script:
describe('File Upload Functionality', () => {
  it('should upload a file successfully', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('#file-upload').attachFile('example.txt');
    cy.get('#file-submit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/upload');
    cy.get('#flash-messages').should('be.visible');
  });

  it('should not upload a file if none is selected', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('#file-submit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/upload');
    cy.get('#flash-messages').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload Functionality', () => {
  test('should upload a file successfully', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    const fileInput = await page.locator('#file-upload');
    await fileInput.setInputFiles('example.txt');
    await page.click('#file-submit');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/upload');
    await expect(page.locator('#flash-messages')).toBeVisible();
  });

  test('should not upload a file if none is selected', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.click('#file-submit');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/upload');
    await expect(page.locator('#flash-messages')).not.toBeVisible();
  });
});
